example.code:
// Component A fetches and stores
const [user, setUser] = useState(null)
useEffect(() => {
  fetch('/api/user').then(r => r.json()).then(setUser)
}, [])

// Component B also fetches same user
const [userData, setUserData] = useState(null)
useEffect(() => {
  fetch('/api/user').then(r => r.json()).then(setUserData)
}, [])

// Component C mutates but other components stay stale
const updateUser = async (data) => {
  await fetch('/api/user', { method: 'PATCH', body: JSON.stringify(data) })
  setUser(data)
}

// Single cache key per entity, any compatible library
const useUser = () => useQuery({
  queryKey: ['user'],
  queryFn: () => api.getUser(),
  staleTime: 60_000,
})

function ProfileSettings() {
  const queryClient = useQueryClient()
  const updateUser = useMutation({
    mutationFn: api.updateUser,
    onMutate: async (newData) => {
      await queryClient.cancelQueries({ queryKey: ['user'] })
      const previous = queryClient.getQueryData(['user'])
      queryClient.setQueryData(['user'], newData)
      return { previous }
    },
    onError: (_e, _v, ctx) => queryClient.setQueryData(['user'], ctx.previous),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: ['user'] }),
  })
}

// Leptos resource as cache, invalidated by mutation signal
let user = create_resource(refetch_signal, |_| async { api::get_user().await });

let update_user = create_action(|data: &UserData| {
    let data = data.clone();
    async move {
        api::update_user(&data).await?;
        Ok::(data)
    }
});

create_effect(move |_| {
    if update_user.version().get() > 0 {
        refetch_signal.set(refetch_signal.get() + 1); // invalidation
    }
});

const [firstName, setFirstName] = useState('John')
const [lastName, setLastName] = useState('Doe')
const [fullName, setFullName] = useState('John Doe') // stored derivation

const updateFirstName = (name) => {
  setFirstName(name)
  setFullName(`${name} ${lastName}`) // manual sync — bug surface
}

